COHORT_RULE_MAP = {
    "Group_1_Low":     "Body Weight Change",
    "Group_2_Mid":     "Serum Glucose",
    "Group_3_High":    "Heart Rate",
    "Group_4_Control": "Alanine Aminotransferase (ALT)",
}

def process_preclinical_data(df: pd.DataFrame, rules_json: dict, project_id: str) -> pd.DataFrame:
    rules_by_param = {r["Assay_Parameter"]: r for r in rules_json["rules"]}

    df = df.copy()
    df["Deviation_Pct"] = (
        (df["Actual_Dose_mg_kg"] - df["Target_Dose_mg_kg"]) / df["Target_Dose_mg_kg"]
    ).abs() * 100
    df["Deviation_Pct"] = df["Deviation_Pct"].round(2)

    statuses, actions, applied_rules = [], [], []

    for _, row in df.iterrows():
        cohort = row.get("Cohort", "")
        param_name = COHORT_RULE_MAP.get(cohort)
        if param_name and param_name in rules_by_param:
            rule = rules_by_param[param_name]
        else:
            # Fallback: most conservative thresholds
            rule = min(rules_json["rules"], key=lambda r: r["Minor_Variance_Limit_Percent"])
            param_name = rule["Assay_Parameter"]

        minor = rule["Minor_Variance_Limit_Percent"]
        major = rule["Major_Variance_Limit_Percent"]
        dev   = row["Deviation_Pct"]

        if dev <= minor:
            statuses.append("INCLUDE")
            actions.append("Approved – within acceptable range")
        elif dev <= major:
            statuses.append("REVIEW")
            actions.append(rule["Action_Required"])
        else:
            statuses.append("EXCLUDE")
            actions.append("Exclude – exceeds major variance limit")

        applied_rules.append(param_name)

    df["Status"]       = statuses
    df["System_Action"] = actions
    df["Applied_Rule"] = applied_rules

    # Stamp each record
    df["Record_ID"]    = [new_record_id(project_id) for _ in range(len(df))]
    df["Import_TS"]    = now_ts()

    return df


def compute_delta(new_df: pd.DataFrame, prev_df: pd.DataFrame) -> pd.DataFrame:
    """Tag rows that are new vs previously seen (by Animal_ID)."""
    if prev_df is None or prev_df.empty:
        new_df = new_df.copy()
        new_df["Delta"] = "NEW"
        return new_df
    prev_ids = set(prev_df["Animal_ID"].astype(str))
    new_df = new_df.copy()
    new_df["Delta"] = new_df["Animal_ID"].astype(str).apply(
        lambda x: "NEW" if x not in prev_ids else "EXISTING"
    )
    return new_df


